memo={}
def dirty(m, stack=()):
    if m in memo: return memo[m]
    if m in stack: return False
    o=ol(m)
    if not os.path.exists(o): memo[m]=("no-olean",); return memo[m]
    if os.path.getmtime(o) < os.path.getmtime(paths[m]): memo[m]=("src-newer",); return memo[m]
