import os, json, collections
P="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
B=os.path.join(P,".lake/build/lib/lean")
d=json.load(open("/tmp/reach.json")); unrooted=set(d["unrooted"]); reach=set(d["reachable"]); paths=d["paths"]

def tracepath(m): return os.path.join(B,"/".join(m.split("."))+".trace")
def walk(x, out):
    if isinstance(x,list):
        if len(x)==2 and isinstance(x[0],str) and isinstance(x[1],str):
            out[x[0]]=x[1]; return
        for y in x: walk(y,out)

rec={}   # module -> {key: hash}
srch={}  # module -> its own source hash as recorded
for m in list(unrooted)+list(reach):
    tp=tracepath(m)
    if not os.path.exists(tp): continue
    try: t=json.load(open(tp))
    except Exception: continue
    out={}; walk(t.get("inputs",[]), out)
    rec[m]=out
    srch[m]=out.get(paths[m])

# authoritative "current" hash for each dep = the value recorded by ROOTED consumers
cur=collections.defaultdict(collections.Counter)
for m in reach:
    for k,v in rec.get(m,{}).items():
        if k.endswith(":importAllArts"): cur[k][v]+=1
# also each module's own recorded source hash from ROOTED consumers isn't available; use source-path key
cursrc={}
for m in reach:
    h=srch.get(m)
    if h: cursrc[m]=h

bad={}
for m in sorted(unrooted):
    if m not in rec: bad[m]="NO TRACE"; continue
    reasons=[]
    for k,v in rec[m].items():
        if k.endswith(":importAllArts"):
            dep=k[:-len(":importAllArts")]
            if k in cur and cur[k] and v not in cur[k]:
                reasons.append("dep "+dep.split('.')[-1]+" hash differs from rooted build")
    if reasons: bad[m]="; ".join(sorted(set(reasons))[:3])
print("UNROOTED with a trace whose recorded import hash disagrees with the rooted build (or no trace):", len(bad))
for m,r in bad.items(): print(f"  {m.replace('AlgebraicJacobian.',''):58s} {r}")
print()
print("no trace at all:", [m.split('.')[-1] for m in sorted(unrooted) if m not in rec])
