def art(m,ext): return os.path.join(B,"/".join(m.split("."))+ext)
def walk(x,out):
    if isinstance(x,list):
        if len(x)==2 and isinstance(x[0],str) and isinstance(x[1],str): out[x[0]]=x[1]; return
        for y in x: walk(y,out)
rec={}
for m in list(unrooted)+list(reach):
    tp=art(m,".trace")
    if os.path.exists(tp):
        try:
            t=json.load(open(tp)); o={}; walk(t.get("inputs",[]),o); rec[m]=o
        except Exception: pass
cur=collections.defaultdict(set)
for m in reach:
    for k,v in rec.get(m,{}).items():
        if k.endswith(":importAllArts"): cur[k].add(v)
edges={}
for m,p in paths.items():
    edges[m]=[l.strip().split()[1] for l in open(p,encoding='utf-8',errors='replace')
              if l.strip().startswith('import ') and l.strip().split()[1].startswith('AlgebraicJacobian.')]
seed={}
for m in sorted(unrooted):
    r=[]
    if not os.path.exists(art(m,".olean")): r.append("no olean (never elaborated)")
    if not os.path.exists(art(m,".trace")): r.append("no trace")
    if os.path.exists(art(m,".trace.nobuild")): r.append("lake .trace.nobuild marker")
    if os.path.exists(art(m,".olean")) and os.path.getmtime(art(m,".olean"))<os.path.getmtime(paths[m]):
        r.append("source newer than olean")
    for k,v in rec.get(m,{}).items():
        if k.endswith(":importAllArts") and k in cur and cur[k] and v not in cur[k]:
            r.append("stale dep hash: "+k[:-len(":importAllArts")].split('.')[-1])
    if r: seed[m]=r
dirty=dict(seed)
changed=True
while changed:
    changed=False
    for m in sorted(unrooted):
        if m in dirty: continue
        for dep in edges.get(m,[]):
            if dep in dirty:
                dirty[m]=["transitively dirty via "+dep.split('.')[-1]]; changed=True; break
print("SEED dirty:", len(seed))
for m,r in sorted(seed.items()): print(f"  {m.replace('AlgebraicJacobian.',''):58s} {'; '.join(sorted(set(r)))}")
print()
print("DIRTY after propagation:", len(dirty), "of", len(unrooted))
print("CLEAN (olean plausibly current):", len(unrooted)-len(dirty))
json.dump({m:sorted(set(v)) for m,v in dirty.items()}, open("/tmp/dirty.json","w"), indent=1)
